import type {
  DaevanionBoardId,
  DaevanionClassId,
  DaevanionVariantId,
  PveBoardId,
} from "./daevanion.ts";

// Checked one-off transfer from aion2-knowledge main@4cf7488:
// combat/daevanion-data.json and combat/daevanion-retained-data.md.
// Exact node geometry and orders; no solver, owner profiles or live source check.
// Import this module dynamically through daevanionLoader, never from the overview.
export type BoardNode = {
  key: string;
  row: number;
  col: number;
  type: "Start" | "Stat" | "SkillLevel";
  grade: string | null;
  cost: number;
  label: string | null;
  short: string;
  stats: { stat: string; value: number }[];
  skillLevels: number;
};

export type BoardGeometry = {
  name: string;
  level: number;
  total: number;
  start: string;
  nodes: BoardNode[];
};

export type PurchaseStep = {
  node: string;
  phase: number;
  cumulativeCost: number;
};

export type PurchaseRoute = {
  total: number;
  phaseEnd: number[];
  targets: string[];
  steps: PurchaseStep[];
};

export type RouteSkill = {
  id: number;
  name: string;
  role: "core" | "damage-core" | "damage" | "utility" | "defensive";
  maxRankTooltip: string;
  sourceUrl: string;
};

export type ClassBoardRoutes = {
  clientBoardId: number;
  skills: Record<string, number>;
  damageTargetCost: number;
  routes: Record<DaevanionVariantId, PurchaseRoute>;
};

export type ClassRoutes = {
  name: string;
  skills: RouteSkill[];
  totals: Record<DaevanionVariantId, number>;
  boards: Record<PveBoardId, ClassBoardRoutes>;
};

export type DaevanionRouteData = {
  provenance: {
    region: string;
    clientBuild: string;
    knowledgeCommit: string;
    sourceChecked: Record<"S124" | "S126" | "S127", string>;
  };
  phases: string[];
  boards: Record<DaevanionBoardId, BoardGeometry>;
  classes: Record<DaevanionClassId, ClassRoutes>;
  azphel: PurchaseRoute & {
    name: string;
    phases: string[];
    variantId: "hp-mp-first";
  };
};

